import React, { useState } from 'react';
import { OrbSmall } from '../components/Orb';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score: 1, emoji: '😔', label: 'Väldigt dåligt' },
  { score: 2, emoji: '😟', label: 'Dåligt' },
  { score: 3, emoji: '😐', label: 'Okej' },
  { score: 4, emoji: '🙂', label: 'Bra' },
  { score: 5, emoji: '😄', label: 'Väldigt bra' },
];

const S = {
  page: { background: '#EEEAE3', minHeight: '100vh', overflowY: 'auto' },
  inner: { padding: '56px 28px 110px', display: 'flex', flexDirection: 'column', minHeight: '100vh' },
  lbl: { fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 12 },
  h: { fontSize: 38, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A', marginBottom: 36 },
  btnPrimary: { width: '100%', padding: 18, borderRadius: 20, background: '#1A2A2A', color: '#EEEAE3', fontSize: 15, fontWeight: 600, letterSpacing: '-0.02em', transition: 'all 0.2s' },
  btnGhost: { width: '100%', padding: 16, borderRadius: 20, background: 'rgba(26,42,42,0.07)', color: '#2D6B6B', fontSize: 15, fontWeight: 500 },
};

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [sel,  setSel]  = useState(null);
  const [note, setNote] = useState('');
  const [step, setStep] = useState('pick');

  const save = () => {
    const m = MOODS[sel];
    addMood(m.score, m.emoji, m.label, note);
    setStep('done');
  };

  const resetAndGo = (pg) => { setSel(null); setNote(''); setStep('pick'); setPage(pg); };

  if (todayChecked && step !== 'done') return (
    <div style={{ ...S.page, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ padding: '0 28px', textAlign: 'center' }}>
        <OrbSmall style={{ margin: '0 auto 32px' }} />
        <h2 style={{ fontSize: 36, fontWeight: 700, letterSpacing: '-0.05em', color: '#1A2A2A', marginBottom: 8 }}>Kom tillbaka imorgon.</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginTop: 36 }}>
          <button onClick={() => setPage('history')} style={S.btnPrimary}>Se historik</button>
          <button onClick={() => setPage('home')}    style={S.btnGhost}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'done') return (
    <div style={{ ...S.page, display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
      <div style={S.inner}>
        <OrbSmall />
        <div style={{ marginTop: 'auto' }}>
          <div style={{ fontSize: 52, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1, color: '#1A2A2A', marginBottom: 8 }}>
            Sparat<span style={{ color: '#2D6B6B' }}>.</span>
          </div>
          <p style={{ fontSize: 14, color: 'rgba(26,42,42,0.38)', marginBottom: 36 }}>Incheckad för idag.</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <button onClick={() => setPage('history')} style={S.btnPrimary}>Se historik</button>
            <button onClick={() => resetAndGo('home')} style={S.btnGhost}>Hem</button>
          </div>
        </div>
      </div>
    </div>
  );

  if (step === 'note') return (
    <div style={S.page}>
      <div style={S.inner}>
        <button onClick={() => setStep('pick')} style={{ fontSize: 13, fontWeight: 500, color: '#2D6B6B', marginBottom: 32, textAlign: 'left' }}>← Ändra</button>
        <div style={{ fontSize: 44, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1, color: '#1A2A2A', marginBottom: 4 }}>{MOODS[sel].label}.</div>
        <p style={{ fontSize: 13, color: 'rgba(26,42,42,0.35)', marginBottom: 28 }}>Vad präglade dagen?</p>
        <div style={{ flex: 1, padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)', display: 'flex', flexDirection: 'column', marginBottom: 14 }}>
          <textarea
            autoFocus
            value={note}
            onChange={e => setNote(e.target.value)}
            maxLength={255}
            placeholder="Valfri notering…"
            style={{ flex: 1, background: 'transparent', border: 'none', outline: 'none', fontSize: 16, lineHeight: 1.7, color: '#1A2A2A', minHeight: 80, resize: 'none' }}
          />
        </div>
        <button onClick={save} style={S.btnPrimary}>Spara</button>
      </div>
    </div>
  );

  return (
    <div style={S.page}>
      <div style={S.inner}>
        <div>
          <p style={S.lbl}>Check-in</p>
          <h2 style={S.h}>Hur mår<br />du idag?</h2>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 5, flex: 1 }}>
          {[...MOODS].reverse().map((m, i) => {
            const idx = 4 - i;
            const isSel = sel === idx;
            return (
              <button
                key={m.score}
                onClick={() => setSel(idx)}
                style={{
                  display: 'flex', alignItems: 'center', gap: 14,
                  padding: '15px 18px', borderRadius: 18,
                  background: isSel ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.38)',
                  border: `1px solid ${isSel ? 'rgba(45,107,107,0.28)' : 'rgba(255,255,255,0.65)'}`,
                  boxShadow: isSel ? '0 4px 20px rgba(45,107,107,0.1)' : 'none',
                  transform: isSel ? 'translateX(6px)' : 'none',
                  transition: 'all 0.25s cubic-bezier(0.34,1.3,0.64,1)',
                  cursor: 'pointer', textAlign: 'left',
                }}
              >
                <span style={{ fontSize: 12, fontWeight: 600, color: isSel ? '#2D6B6B' : 'rgba(26,42,42,0.18)', width: 18, transition: 'color 0.2s' }}>{m.score}</span>
                <span style={{ fontSize: 22 }}>{m.emoji}</span>
                <span style={{ fontSize: 16, fontWeight: 500, color: isSel ? '#1A2A2A' : 'rgba(26,42,42,0.45)', letterSpacing: '-0.02em', transition: 'color 0.2s' }}>{m.label}</span>
                <span style={{ marginLeft: 'auto', fontSize: 13, color: isSel ? '#2D6B6B' : 'rgba(26,42,42,0.12)', transition: 'all 0.2s' }}>›</span>
              </button>
            );
          })}
        </div>
        <button
          onClick={() => sel !== null && setStep('note')}
          disabled={sel === null}
          style={{ ...S.btnPrimary, marginTop: 14, opacity: sel === null ? 0.3 : 1 }}
        >
          Fortsätt
        </button>
      </div>
    </div>
  );
}
